@IsTest
private class AddressVerificationServiceTest {

    /**
     * Generic mock that records the request, counts calls and returns a
     * configurable response so we can assert the full API contract.
     */
    private class AddressMock implements HttpCalloutMock {
        public Integer statusCode = 200;
        public String responseBody = '{}';
        public Integer callCount = 0;
        public HttpRequest lastRequest = null;

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            lastRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            res.setBody(responseBody);
            return res;
        }
    }

    private static Account buildAccount(String street) {
        Account a = new Account(
            Name = 'Test Acct',
            BillingStreet = street,
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
        );
        return a;
    }

    /* SKIPPED path: blank BillingStreet -> no callout */
    @IsTest
    static void testSkippedWhenBlankStreet() {
        AddressMock mock = new AddressMock();
        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(buildAccount('   '));
        Test.stopTest();
        System.assertEquals('SKIPPED', r.status);
        System.assertEquals(false, r.changed);
        System.assertEquals(0, mock.callCount, 'No callout should be made for blank street');
    }

    @IsTest
    static void testSkippedWhenNullStreet() {
        AddressMock mock = new AddressMock();
        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(buildAccount(null));
        Test.stopTest();
        System.assertEquals('SKIPPED', r.status);
        System.assertEquals(0, mock.callCount);
    }

    /* VERIFIED path + full request contract */
    @IsTest
    static void testVerifiedRequestContract() {
        AddressMock mock = new AddressMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"VERIFIED","address":{"street":"x","city":"y","postalCode":"z","country":"c"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = buildAccount('1 Main St');
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('VERIFIED', r.status);
        System.assertEquals(false, r.changed);
        // account untouched
        System.assertEquals('1 Main St', a.BillingStreet);
        System.assertEquals('Springfield', a.BillingCity);

        // request contract
        System.assertEquals(1, mock.callCount);
        HttpRequest req = mock.lastRequest;
        System.assertEquals('callout:FB_Address_API/v2/verify', req.getEndpoint());
        System.assertEquals('POST', req.getMethod());
        System.assertEquals('application/json', req.getHeader('Content-Type'));

        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        System.assertEquals('1 Main St', body.get('street'));
        System.assertEquals('Springfield', body.get('city'));
        System.assertEquals('12345', body.get('postalCode'));
        System.assertEquals('USA', body.get('country'));
    }

    /* CORRECTED path overwrites account fields */
    @IsTest
    static void testCorrectedOverwritesAccount() {
        AddressMock mock = new AddressMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"CORRECTED","address":{"street":"New St","city":"NewCity","postalCode":"99999","country":"Canada"}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = buildAccount('1 Main St');
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('CORRECTED', r.status);
        System.assertEquals(true, r.changed);
        System.assertEquals('New St', a.BillingStreet);
        System.assertEquals('NewCity', a.BillingCity);
        System.assertEquals('99999', a.BillingPostalCode);
        System.assertEquals('Canada', a.BillingCountry);
    }

    /* INVALID path: status returned, no change */
    @IsTest
    static void testInvalidNoChange() {
        AddressMock mock = new AddressMock();
        mock.statusCode = 200;
        mock.responseBody = '{"status":"INVALID","address":{"street":"","city":"","postalCode":"","country":""}}';
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = buildAccount('1 Main St');
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('INVALID', r.status);
        System.assertEquals(false, r.changed);
        System.assertEquals('1 Main St', a.BillingStreet);
    }

    /* Non-200 throws with status code in message */
    @IsTest
    static void testThrowsOnNon200() {
        AddressMock mock = new AddressMock();
        mock.statusCode = 404;
        mock.responseBody = 'Not Found';
        Test.setMock(HttpCalloutMock.class, mock);

        Account a = buildAccount('1 Main St');
        Boolean threw = false;
        try {
            Test.startTest();
            AddressVerificationService.verify(a);
            Test.stopTest();
        } catch (AddressVerificationService.AddressVerificationException e) {
            threw = true;
            System.assert(e.getMessage().contains('404'), 'message must contain status code: ' + e.getMessage());
        }
        System.assert(threw, 'Expected AddressVerificationException');
    }

    @IsTest
    static void testThrowsOn500() {
        AddressMock mock = new AddressMock();
        mock.statusCode = 500;
        Test.setMock(HttpCalloutMock.class, mock);
        Account a = buildAccount('1 Main St');
        Boolean threw = false;
        try {
            Test.startTest();
            AddressVerificationService.verify(a);
            Test.stopTest();
        } catch (AddressVerificationService.AddressVerificationException e) {
            threw = true;
            System.assert(e.getMessage().contains('500'));
        }
        System.assert(threw);
    }
}
