public with sharing class PicklistService {

    public class Option {
        public String value { get; private set; }
        public String label { get; private set; }
        public Boolean isDefault { get; private set; }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('objectApiName must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('fieldApiName must not be null or blank.');
        }

        String objKey = objectApiName.toLowerCase();
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        if (!globalMap.containsKey(objKey)) {
            throw new PicklistServiceException(
                'Object "' + objectApiName + '" was not found in this org.'
            );
        }
        Schema.SObjectType sType = globalMap.get(objKey);

        String fldKey = fieldApiName.toLowerCase();
        Map<String, Schema.SObjectField> fieldMap = sType.getDescribe().fields.getMap();
        if (!fieldMap.containsKey(fldKey)) {
            throw new PicklistServiceException(
                'Field "' + fieldApiName + '" was not found on object "' + objectApiName + '".'
            );
        }
        Schema.SObjectField sField = fieldMap.get(fldKey);
        Schema.DescribeFieldResult fldResult = sField.getDescribe();

        Schema.DisplayType dtype = fldResult.getType();
        if (dtype != Schema.DisplayType.Picklist && dtype != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field "' + fieldApiName + '" is not a picklist or multi-select picklist field.'
            );
        }

        List<Option> results = new List<Option>();
        for (Schema.PicklistEntry entry : fldResult.getPicklistValues()) {
            if (entry.isActive()) {
                results.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return results;
    }
}
