public class AccountScoringJob implements Queueable, Database.Stateful {

    private List<Id> accountIds;
    private Integer offset;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds != null) ? accountIds : new List<Id>();
        this.offset = 0;
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return (Id) System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        if (offset >= accountIds.size()) {
            return;
        }

        List<Id> batch = new List<Id>();
        Integer nextOffset = Math.min(offset + 200, accountIds.size());

        for (Integer i = offset; i < nextOffset; i++) {
            batch.add(accountIds[i]);
        }

        offset = nextOffset;

        // One SOQL
        List<Account> accounts = [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batch];

        // Set Rating from AnnualRevenue
        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        // One DML
        update accounts;

        // Chain remaining
        if (offset < accountIds.size()) {
            System.enqueueJob(this);
        }
    }
}
