/**
 * Domain contract for Account collections.
 *
 * Built on the "newer" fflib domain structure where a domain is simply a
 * typed collection on top of fflib_SObjects. It carries no trigger logic —
 * trigger handling lives in the class handed to Application.TriggerFactory.
 */
public interface IAccounts extends fflib_ISObjects
{
    /** The underlying Account records held by this domain instance. */
    List<Account> getAccounts();

    /**
     * Returns a NEW domain (an IAccounts) containing only the records whose
     * Rating equals the supplied value. Never mutates the current domain.
     * If nothing matches, an empty domain is returned.
