/**
 * Account domain class following the newer fflib "plain collection" pattern.
 *
 * The domain itself is just a list-aware wrapper over fflib_SObjects; it holds
 * no trigger logic. All construction must funnel through the Application.Domain
 * factory so unit tests can transparently swap in a mock via
 * Application.Domain.setMock().
 */
public class Accounts extends fflib_SObjects implements IAccounts
{
    public Accounts(List<SObject> records)
    {
        super(records);
    }

    // -------------------------------------------------------------------------
    // Factory entry points — delegate to Application.Domain so a mock domain
    // installed via Application.Domain.setMock() is honoured.
    // -------------------------------------------------------------------------

    /** Wraps the supplied records into a domain instance via the factory. */
    public static IAccounts newInstance(List<Account> records)
    {
        return (Accounts) Application.Domain.newInstance(records);
    }

    /**
     * Loads the supplied Account Ids through the factory's selector (the
     * factory owns the selector wiring), then wraps them into a domain.
     */
    public static IAccounts newInstance(Set<Id> accountIds)
    {
        return (Accounts) Application.Domain.newInstance(accountIds);
    }

    /**
     * Non-static inner bean referenced by Application.Domain's type map
     * (Account.SObjectType => Accounts.Constructor.class). The factory builds
     * it reflectively via Type.newInstance() and calls build(List<SObject>).
     */
    public class Constructor implements fflib_Application.DomainFactory.Constructor
    {
        public fflib_ISObjects build(List<SObject> records)
        {
            return new Accounts(records);
        }
    }

    // -------------------------------------------------------------------------
    // fflib_ISObjects / IAccounts contract
    // -------------------------------------------------------------------------

    /** Always reports Account, even for an empty domain instance. */
    public override Schema.SObjectType getSObjectType()
    {
        return Account.SObjectType;
    }

    /** Convenience accessor kept consistent with getSObjectType(). */
    public override Schema.SObjectType getType()
    {
        return Account.SObjectType;
    }

    /** Returns the records typed as List<Account>. */
    public List<Account> getAccounts()
    {
        return (List<Account>) all();
    }

    // -------------------------------------------------------------------------
    // Domain behaviour
    // -------------------------------------------------------------------------

    /**
     * Returns a new domain filtered to those records whose Rating equals the
     * supplied value. The current instance is left untouched; an empty domain
     * is returned when nothing matches.
     */
    public IAccounts selectByRating(String rating)
    {
        List<Account> matches = new List<Account>();
        for (Account record : getAccounts())
        {
            if (record.Rating == rating)
            {
                matches.add(record);
            }
        }
        return newInstance(matches);
    }

    /** Distinct set of non-null OwnerId values across this domain. */
    public Set<Id> getOwnerIds()
    {
        Set<Id> ownerIds = new Set<Id>();
        for (Account record : getAccounts())
        {
            if (record.OwnerId != null)
            {
                ownerIds.add(record.OwnerId);
            }
        }
        return ownerIds;
    }

    /** Sets Rating on every record in this domain (in-place, not returned). */
    public void setRating(String rating)
    {
        for (Account record : getAccounts())
        {
            record.Rating = rating;
        }
    }
}
