    private List<String> getFieldNamesForQuery() {
        List<String> names = new List<String>();
        Set<String> seen = new Set<String>();

        for (Schema.SObjectField f : getSObjectFieldList()) {
            String name = f.getDescribe().getName();
            if (!seen.contains(name)) {
                seen.add(name);
                names.add(name);
            }
        }

        Schema.FieldSet creditFieldSet = Account.SObjectType.getDescribe()
            .fieldSets.getMap().get('Credit_Review');
        if (creditFieldSet != null) {
            for (Schema.FieldSetMember fsm : creditFieldSet.getFields()) {
                String fieldPath = fsm.getFieldPath();
                if (!seen.contains(fieldPath)) {
                    seen.add(fieldPath);
                    names.add(fieldPath);
                }
            }
        }

        return names;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        List<String> fieldNames = getFieldNamesForQuery();
        String query = 'SELECT ' + String.join(fieldNames, ', ')
            + ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';
        return Database.query(query);
