```java
public with sharing class AccountOnboardingService {

    /**
     * Creates one Account per map entry and Contacts for each last name listed,
     * all orchestrated through a single fflib_SObjectUnitOfWork commit.
     *
     * @param contactLastNamesByAccountName  key = Account Name, value = list of Contact LastNames
     * @return the newly inserted Accounts with populated Ids
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // SObject_Type[] constructor defines insert ordering: Accounts before Contacts,
        // which keeps this bulk-safe for hundreds of records in a single transaction.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new fflib_SObjectUnitOfWork.SObject_Type[]{
                new fflib_SObjectUnitOfWork.SObject_Type(new Account()),
                new fflib_SObjectUnitOfWork.SObject_Type(new Contact())
            }
        );

        // Apex Maps have no Map.Entry; iterate keys and look values up by key.
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            uow.registerNew(acc);
            newAccounts.add(acc);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName);
                    uow.registerNew(con);
                    // Declare the parent→child dependency. The UoW inserts the Account
                    // first, then populates Contact.AccountId before inserting the Contact.
                    uow.registerRelationship(acc, con, Contact.AccountId);
                }
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
