public inherited sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load via selector (single bulk SOQL).
        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Skip anything already Closed Won; stamp the rest.
        Date today = Date.today();
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opps) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = today;
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // One fflib unit of work, obtained from the Application factory and committed once.
        // The factory's newInstance() hands back the concrete fflib_Application.SObjectUnitOfWork
        // (the implementation that supports platform-event publishing), so we cast to that type.
        // fflib's commit() does the DML FIRST and only THEN publishes the queued events via the
        // EventBus; if the DML throws, commit() propagates the exception and NO event is published
        // -> Fulfilment never hears about a deal that was not actually saved. We never call
        // EventBus.publish() ourselves.
        fflib_Application.SObjectUnitOfWork uow =
            (fflib_Application.SObjectUnitOfWork) Application.UnitOfWork.newInstance();

        for (Opportunity opp : toClose) {
            uow.registerDirty(opp);

            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Amount__c = opp.Amount;
            uow.registerPublish(evt);
        }

        // Single commit: DML committed successfully, then events published.
        uow.commit();

        return toClose.size();
    }
}
