trigger AccountTrigger on Account (after insert) {
    if (Trigger.new == null || Trigger.new.isEmpty()) return;

    List<String> ids = new List<String>();
    for (Account a : Trigger.new) {
        ids.add(a.Id);
    }

    // @Future(callout=true) allows up to 100 HTTP callouts per execution.
    // Split batches > 100 into chunks so we stay under the governor limit.
    Integer chunkSize = 100;
    for (Integer start = 0; start < ids.size(); start += chunkSize) {
        Integer stop = Math.min(start + chunkSize, ids.size());
        List<String> chunk = ids.getSubset(start, stop);
        ErpCustomerSync.pushAccounts(chunk);
