/**
 * Asynchronously pushes each newly-created Account to the ERP as a separate
 * customer record so the ERP team can trace every account individually.
 *
 * One POST per Account:
 *   POST callout:ERP/api/customers
 *   Body: [{"salesforceId":"001…","name":"…","country":"…"}]
 *
 * @Future(callout=true) is used because:
 *   - Synchronous callouts are prohibited from trigger context.
 *   - Queueable only grants 10 callouts per execution, requiring
 *     20 chained re-enqueues for a 200-account batch.
 *   - @Future(callout=true) grants 100 callouts per transaction,
 *     letting a single invocation handle an entire batch.
 *   - The trigger pre-splits >100-account batches into chunks so each
 *     future call stays within the 100-callout governor limit.
 */
public class ErpCustomerSync {

    @Future(callout = true)
    public static void pushAccounts(List<String> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
            ORDER BY Id
        ];

        for (Account acc : accounts) {
            // country must be null when BillingCountry is blank
            String country = String.isNotBlank(acc.BillingCountry)
                ? acc.BillingCountry
                : null;

            // One request per account so the ERP team can trace every record
            List<Map<String, Object>> body = new List<Map<String, Object>>{
                new Map<String, Object>{
                    'salesforceId' => (String) acc.Id,
                    'name'         => acc.Name,
                    'country'      => country
                }
            };

            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(JSON.serialize(body));

            Http http = new Http();
            HttpResponse res = http.send(req);

            // Expected response: 202 Accepted.
            // Error handling / retries are out of scope for this ticket.
        }
