public class GiftImportService {

    // Payload the integration sends in (one web gift).
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;     // donor's personal email (the matching key NPSP uses by default)
        public Decimal amount;
        public Date giftDate;
    }

    // Per-row outcome, built from the staged NPSP Data Import record.
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // matched or newly created Contact
        public Id opportunityId;    // created Donation (Opportunity)
        public String errorMessage; // NPSP failure detail when success == false
    }

    /**
     * Stage one NPSP Data Import record per gift, process them synchronously in this
     * transaction via NPSP's Apex Data Import API (so the org's npsp__Data_Import_Settings__c
     * match/unmatch rules, household creation and donation processing all apply), then read the
     * results straight back off the staged records (which remain in the org as the audit trail).
     *
     * The staged records are NOT deleted. One bad row never stops the rest: NPSP records the
     * failure on the individual Data Import row, and any hard failure that escapes NPSP's own
     * error handling is contained per record.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results; // null / empty -> empty list
        }

        Integer total = gifts.size();

        // Pre-fill results list so we can address it strictly by input order.
        for (Integer i = 0; i < total; i++) {
            results.add(null);
        }

        // ---- 1. Stage one Data Import record per gift ----
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Status__c = 'New';                    // staged, awaiting processing
            di.npsp__Donation_Donor__c = 'Contact1';       // match the personal Contact
            di.npsp__Contact1_Firstname__c = g.firstName;
            di.npsp__Contact1_Lastname__c = g.lastName;
            di.npsp__Contact1_Personal_Email__c = g.email;
            di.npsp__Donation_Amount__c = g.amount;
            di.npsp__Donation_Date__c = g.giftDate;
            staged.add(di);
        }

        // Bulk-safe insert (partial success allowed) and remember which record backs which gift.
        Database.SaveResult[] inserts = Database.insert(staged, false);
        Set<Id> stagedIds = new Set<Id>();
        Map<Id, Integer> idToIndex = new Map<Id, Integer>();

        for (Integer i = 0; i < inserts.size(); i++) {
            Database.SaveResult sr = inserts[i];
            if (sr.isSuccess()) {
                Id diId = sr.getId();
                stagedIds.add(diId);
                idToIndex.put(diId, i);
                // results[i] stays null here; filled from the processed record below.
            } else {
                // Could not even stage the row -> report as failure, keep others going.
                String msg = (sr.getErrors() != null && !sr.getErrors().isEmpty())
                        ? sr.getErrors()[0].getMessage()
                        : 'Unable to stage the NPSP Data Import record.';
                ImportResult failed = new ImportResult();
                failed.success = false;
                failed.errorMessage = msg;
                results[i] = failed;
            }
        }

        // ---- 2. Process staged records synchronously, in this transaction, via NPSP's API ----
        if (!stagedIds.isEmpty()) {
            try {
                // Synchronous per-record processing of the staged import set.
                npsp.BDI_DataImport_API.processSingleBatches(stagedIds);
            } catch (Exception ex) {
                // A global processing failure is contained; rows still in 'New' are reported as
                // failed with NPSP/transaction detail so they do not masquerade as imported.
                for (Integer i = 0; i < total; i++) {
                    if (results[i] == null) {
                        ImportResult r = new ImportResult();
                        r.success = false;
                        r.errorMessage = 'Data Import processing error: ' + ex.getMessage();
                        results[i] = r;
                    }
                }
                // Anything that DID process will be corrected by the query below.
            }
        }

        // ---- 3. Read results back off the staged records (the audit trail) ----
        if (!idToIndex.isEmpty()) {
            for (npsp__DataImport__c di : [
                    SELECT Id,
                           npsp__Status__c,
                           npsp__Contact1Imported__c,
                           npsp__DonationImported__c,
                           npsp__FailureInformation__c
                    FROM npsp__DataImport__c
                    WHERE Id IN :idToIndex.keySet()
            ]) {
                Integer idx = idToIndex.get(di.Id);
                Boolean imported = (di.npsp__Status__c == 'Imported');

                ImportResult r = new ImportResult();
                r.success = imported;
                r.contactId = di.npsp__Contact1Imported__c;
                r.opportunityId = di.npsp__DonationImported__c;
                if (!imported) {
                    r.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                            ? di.npsp__FailureInformation__c
                            : 'NPSP did not import this record (Status: ' + di.npsp__Status__c + ').';
                }
                results[idx] = r; // overwrite by input order
            }
        }

        // Safety net: any null slot means the row was neither staged nor processed -> failed.
        for (Integer i = 0; i < total; i++) {
            if (results[i] == null) {
                ImportResult r = new ImportResult();
                r.success = false;
                r.errorMessage = 'Gift was not processed by NPSP Data Import.';
                results[i] = r;
            }
        }

        return results;
    }
}
