public with sharing class HouseholdService {

    /**
     * Creates a new NPSP Household Account and inserts the supplied contacts
     * so that they all belong to that single household. The first contact
     * in the list is designated as the primary contact.
     *
     * @param  members  list of new (unsaved) Contacts
     * @return          Id of the newly created Household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        // ── Guard clause ──────────────────────────────────────────────
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'The members list must not be null or empty.'
            );
        }

        // ── Resolve the Household Account record type by DeveloperName ─
        Map<String, Schema.RecordTypeInfo> accountRtMap =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName();
        Schema.RecordTypeInfo householdRt = accountRtMap.get('HH_Account');
        if (householdRt == null) {
            throw new IllegalArgumentException(
                'Account record type with DeveloperName "HH_Account" was not found.'
            );
        }
        Id householdRecordTypeId = householdRt.getId();

        // ── Create the household Account ───────────────────────────────
        // Do NOT set Name; NPSP household-naming rules will generate it
        // and produce the appropriate greeting after contacts are inserted.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId
        );
        insert household;   // single DML – no loop

        // ── Link every new Contact to this single household ────────────
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;     // bulk DML

        // ── Designate the first Contact as the primary contact ─────────
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
