            new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            // After DML, get the actual Id (populated by insert or unchanged by update)
            String ocrId = String.valueOf(ocrPerReq[i].Id);
            if (ocrId == null) {
                // Should not happen after DML, but guard
                ocrId = 'null';
            }

            Map<Id, npsp__Partial_Soft_Credit__c> contactMap =
                pscMap.get(req.opportunityId);
            npsp__Partial_Soft_Credit__c psc =
                (contactMap != null) ? contactMap.get(req.contactId) : null;

            if (psc != null) {
                // Fresh SObject to only send fields we want to change
                npsp__Partial_Soft_Credit__c updatePsc = new npsp__Partial_Soft_Credit__c();
                updatePsc.Id = psc.Id;
                updatePsc.npsp__Amount__c = req.amount;
                updatePsc.npsp__Role_Name__c = req.role;
                updatePsc.npsp__Contact_Role_ID__c = ocrId;
                pscsToUpdate.add(updatePsc);
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocrId
                );
                pscsToInsert.add(newPsc);
            }
        }

        // DML 3 & 4: PSCs
        if (!pscsToInsert.isEmpty()) insert pscsToInsert;
        if (!pscsToUpdate.isEmpty()) update pscsToUpdate;
