public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        DmlWrapper dmlWrapper = new DmlWrapper();
        List<Opportunity> qualifiedOpportunities = new List<Opportunity>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject s : newlist) {
                Opportunity opp = (Opportunity) s;
                if (isQualified(opp.StageName, opp.Amount)) {
                    qualifiedOpportunities.add(opp);
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];
                if (isQualified(newOpp.StageName, newOpp.Amount)
                        && !isQualified(oldOpp.StageName, oldOpp.Amount)) {
                    qualifiedOpportunities.add(newOpp);
                }
            }
        }

        if (!qualifiedOpportunities.isEmpty()) {
            List<Task> tasksToInsert = new List<Task>();
            for (Opportunity opp : qualifiedOpportunities) {
                Task t = new Task();
                t.Subject      = 'Major gift thank-you call';
                t.Priority     = 'High';
                t.Status       = 'Not Started';
                t.WhatId       = opp.Id;
                t.WhoId        = (Id) opp.npsp__Primary_Contact__c;
                t.OwnerId      = opp.OwnerId;
                t.ActivityDate = opp.CloseDate.addDays(3);
                tasksToInsert.add(t);
            }
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private static Boolean isQualified(String stageName, Decimal amount) {
        return stageName == 'Closed Won'
            && amount != null
            && amount >= 5000;
    }
}
